public class Main {
    static String observe(Thread t, Thread.State want) throws InterruptedException {
        long deadline = System.currentTimeMillis() + 3000L;
        while (System.currentTimeMillis() < deadline) {
            if (t.getState() == want) return want.name();
            Thread.sleep(2L);
        }
        return "not-observed(" + t.getState().name() + ")";
    }

    public static void main(String[] args) throws Exception {
        final Object lock = new Object();

        Thread sleeper = new Thread(() -> {
            try { Thread.sleep(400L); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        }, "sleeper");
        System.out.println("1) before start()       : " + sleeper.getState().name());
        sleeper.start();
        System.out.println("2) inside sleep(400)    : " + observe(sleeper, Thread.State.TIMED_WAITING));

        Thread holder = new Thread(() -> {
            synchronized (lock) {
                try { Thread.sleep(400L); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            }
        }, "holder");
        Thread waiter = new Thread(() -> { synchronized (lock) { } }, "waiter");
        holder.start();
        Thread.sleep(80L);
        waiter.start();
        System.out.println("3) waiting for monitor  : " + observe(waiter, Thread.State.BLOCKED));

        final Thread inner = new Thread(() -> {
            try { Thread.sleep(400L); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        }, "inner");
        Thread joiner = new Thread(() -> {
            try { inner.join(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        }, "joiner");
        inner.start();
        joiner.start();
        System.out.println("4) inside join()        : " + observe(joiner, Thread.State.WAITING));

        holder.join();
        waiter.join();
        sleeper.join();
        System.out.println("5) after join()         : " + sleeper.getState().name());
    }
}
